import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import ReactConfetti from 'react-confetti';

export default function SolicitacaoManutencao() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    nome_solicitante: '',
    setor: '',
    titulo: '',
    local: '',
    descricao: ''
  });
  const [mensagem, setMensagem] = useState<{ tipo: 'sucesso' | 'erro'; texto: string } | null>(null);
  const [loading, setLoading] = useState(false);
  const [showConfetti, setShowConfetti] = useState(false);
  const [windowSize, setWindowSize] = useState({
    width: window.innerWidth,
    height: window.innerHeight
  });

  // Atualizar tamanho da janela quando redimensionar
  window.addEventListener('resize', () => {
    setWindowSize({
      width: window.innerWidth,
      height: window.innerHeight
    });
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMensagem(null);

    try {
      await axios.post('http://localhost:3001/api/solicitacoes', formData);
      setMensagem({ tipo: 'sucesso', texto: 'Solicitação enviada com sucesso!' });
      setShowConfetti(true);
      setFormData({
        nome_solicitante: '',
        setor: '',
        titulo: '',
        local: '',
        descricao: ''
      });

      // Esconder o confete após 5 segundos
      setTimeout(() => {
        setShowConfetti(false);
      }, 5000);
    } catch (error) {
      setMensagem({ tipo: 'erro', texto: 'Erro ao enviar solicitação. Tente novamente.' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-blue-100 py-12 px-4 sm:px-6 lg:px-8">
      {showConfetti && (
        <ReactConfetti
          width={windowSize.width}
          height={windowSize.height}
          recycle={false}
          numberOfPieces={500}
          gravity={0.3}
        />
      )}
      
      <div className="max-w-3xl mx-auto">
        <div className="text-center mb-12">
          <img 
            src="/logo-anglo.jpg" 
            alt="Logo Anglo" 
            className="mx-auto h-24 w-auto mb-6"
          />
          <h1 className="text-3xl font-extrabold text-gray-900 mb-2">
            Solicitação de Manutenção
          </h1>
          <p className="text-lg text-gray-600">
            Preencha o formulário abaixo para solicitar uma manutenção
          </p>
        </div>

        <div className="bg-white shadow-xl rounded-lg p-8">
          {mensagem && (
            <div className={`mb-6 p-4 rounded-md ${
              mensagem.tipo === 'sucesso' 
                ? 'bg-green-50 text-green-700 border border-green-200' 
                : 'bg-red-50 text-red-700 border border-red-200'
            }`}>
              <div className="flex items-center">
                {mensagem.tipo === 'sucesso' ? (
                  <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                  </svg>
                ) : (
                  <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                )}
                <p className="text-sm font-medium">{mensagem.texto}</p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label htmlFor="nome_solicitante" className="block text-sm font-medium text-gray-700">
                  Nome do Solicitante
                </label>
                <input
                  type="text"
                  id="nome_solicitante"
                  name="nome_solicitante"
                  value={formData.nome_solicitante}
                  onChange={(e) => setFormData({ ...formData, nome_solicitante: e.target.value })}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                  required
                />
              </div>

              <div>
                <label htmlFor="setor" className="block text-sm font-medium text-gray-700">
                  Setor
                </label>
                <input
                  type="text"
                  id="setor"
                  name="setor"
                  value={formData.setor}
                  onChange={(e) => setFormData({ ...formData, setor: e.target.value })}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                  required
                />
              </div>
            </div>

            <div>
              <label htmlFor="titulo" className="block text-sm font-medium text-gray-700">
                Título da Manutenção
              </label>
              <input
                type="text"
                id="titulo"
                name="titulo"
                value={formData.titulo}
                onChange={(e) => setFormData({ ...formData, titulo: e.target.value })}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </div>

            <div>
              <label htmlFor="local" className="block text-sm font-medium text-gray-700">
                Local da Manutenção
              </label>
              <input
                type="text"
                id="local"
                name="local"
                value={formData.local}
                onChange={(e) => setFormData({ ...formData, local: e.target.value })}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </div>

            <div>
              <label htmlFor="descricao" className="block text-sm font-medium text-gray-700">
                Descrição Detalhada
              </label>
              <textarea
                id="descricao"
                name="descricao"
                rows={4}
                value={formData.descricao}
                onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm"
                required
              />
            </div>

            <div className="flex justify-end space-x-4">
              <button
                type="button"
                onClick={() => navigate('/')}
                className="px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                Voltar
              </button>
              <button
                type="submit"
                disabled={loading}
                className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? (
                  <span className="flex items-center">
                    <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                    </svg>
                    Enviando...
                  </span>
                ) : (
                  'Enviar Solicitação'
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}
